/*
 * A266502  Triangle read by rows giving successive states of cellular
 *          automaton generated by "Rule 28" initiated with a single ON
 *          (black) cell.
 * https://oeis.org/A266502
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, tabf, easy
 * Formula:   not stated
 * Range:     u8 n <= 9581, u16 n <= 9581, u32 n <= 9581, u64 n <= 9581,
 *            u128 n <= 9581, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence A266502: Triangle of successive states of Rule 28
   (or Rule 156) with a single ON cell.  The triangle is read row by
   row, left‑to‑right.  The element a(n) occurs at index n in the
   flat ordering.  This implementation constructs rows incrementally
   until the row containing n is reached and returns the appropriate
   cell. */
#include <stdint.h>
#include <stdlib.h>
#include <stdbool.h>

/* Integer floor square root for unsigned 64‑bit values. */
static idx_t int_sqrt(idx_t n)
{
    idx_t lo = 0, hi = (idx_t)1ULL << 32;          /* sqrt(2^64‑1) < 2^32 */
    idx_t ans = 0;
    while (lo <= hi) {
        idx_t mid = lo + ((hi - lo) >> 1);
        unsigned __int128 sq = (unsigned __int128)mid * mid;
        if (sq <= n) {
            ans = mid;
            lo = mid + 1;
        } else {
            if (mid == 0) break;
            hi = mid - 1;
        }
    }
    return ans;
}

/* Return the n-th term of A266502. */
seq_t a(idx_t n)
{
    /* Determine the row r that contains index n. */
    idx_t r = int_sqrt(n);          /* floor(sqrt(n)) */
    idx_t base = r * r;             /* first index of row r */
    idx_t offset = n - base;        /* zero‑based position within row r */

    /* Row 0 is the single ON cell. */
    if (r == 0) {
        return (seq_t)1;
    }

    /* Allocate the first row. */
    uint8_t *prev = (uint8_t *)malloc(1);
    if (!prev) return 0;            /* unlikely */
    prev[0] = 1;                    /* row 0 */

    /* Generate rows 1 .. r. */
    for (idx_t i = 1; i <= r; ++i) {
        idx_t newLen = 2 * i + 1;                 /* length of new row */
        uint8_t *next = (uint8_t *)malloc(newLen);
        if (!next) { free(prev); return 0; }
        idx_t lenPrev = 2 * (i - 1) + 1;          /* length of previous row */

        for (idx_t k = 0; k < newLen; ++k) {
            /* Determine neighbors of the cell at new position k. */
            uint8_t left   = (k >= 2 && k - 2 < lenPrev) ? prev[k - 2] : 0;
            uint8_t center = (k >= 1 && k - 1 < lenPrev) ? prev[k - 1] : 0;
            uint8_t right  = (k < lenPrev)                   ? prev[k]     : 0;

            /* Rule 28: 100, 011, 010 → 1; all others → 0. */
            next[k] = ((left   == 1 && center == 0 && right  == 0) ||
                       (left   == 0 && center == 1 && right  == 1) ||
                       (left   == 0 && center == 1 && right  == 0)) ? 1 : 0;
        }
        free(prev);
        prev = next;
    }

    /* Retrieve the requested element from the final row. */
    uint8_t val = prev[offset];
    free(prev);
    return (seq_t)val;
}
